fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // Specification for rsplit:
    // - For each input string s in a:
    //   - if maxsplit == 0, output is vec![s.clone()] (no splitting).
    //   - else:
    //       - if s.is_empty(), output is vec!["".to_string()]
    //       - else output is s split from right on `sep` with at most maxsplit splits,
    //         producing <= maxsplit+1 parts, returned in left-to-right order.
    //
    // Additional properties:
    // - output vector length == input vector length
    // - for each inner vector, concatenating the parts with `sep` in between yields s

    // Since this function is pure and deterministic, we specify for all i:
    // a[i] and result[i] satisfy above conditions, and result.len() == a.len()

    // No preconditions on a, sep, or maxsplit. (maxsplit as u8)

    // This function uses rsplitn with (maxsplit + 1) parts from the right.

    if maxsplit == 0 {
        // ensures: result.len() == a.len()
        // for all i, result[i] == vec![a[i].clone()]
        return a.into_iter().map(|s| vec![s]).collect();
    }

    let sep = &sep;

    a.into_iter()
        .map(|s| {
            // ensures: if s.is_empty() then result == vec!["".to_string()]
            // else result is s split from right by sep with <= maxsplit splits, reversed to normal order.
            if s.is_empty() {
                return vec![String::new()];
            }

            let parts: Vec<String> = s.rsplitn((maxsplit as usize) + 1, sep)
                .map(|part| part.to_string())
                .collect();

            let mut parts = parts;
            parts.reverse();
            parts
        })
        .collect()
}